factory_as_code_schema.extension_example:
apiVersion: repo-agent-os/v1alpha1
kind: Factory
metadata: {name: payments, revision: 17}
spec:
  imports:
    - {ref: warp-factory, version: v1alpha1, digest: sha256:...}
  roles:
    implement: {identity: app/implement, capabilities: [git.branch.write], writes: [patch,test_result]}
    verify: {identity: app/verify, capabilities: [repo.read,ci.run], independentOf: [implement]}
  workflow:
    initial: INTAKE_RECEIVED
    states:
      READY: {on: [{event: claim, to: BUILD_ACTIVE, guard: ready_and_fenced}]}
      BUILD_ACTIVE: {timeout: PT2H, retry: bounded_transient, cleanup: workspace_cleanup}
    phases:
      build: {role: implement, inputs: [spec@digest,base@sha], outputs: [patch,test_result]}
      verify: {role: verify, needs: [build], join: ALL, outputs: [verification]}
  interaction:
    decisions: {appendOnly: true, requireHumanAccept: product_intent, invalidateDependents: true}
  budgets: {usd: 25, wall: PT4H, children: 4, retries: 2}
  gates:
    spec: {authority: product-owner, binds: [spec,definition,policy]}
    promotion: {authority: platform-owner, protected: true}
  evaluation:
    protectedRef: evals@sha256:...
    offline: {minCases: 50, repeats: 3, nonInferiority: 0.02}
    shadow: {minDays: 14}
    canary: {maxPercent: 5, autoRollbackOn: [invariant_failure,slo_breach]}
  reconciliation: {mode: preserve-unknown, interval: PT15M}
